@pytest.mark.asyncio @pytest.mark.parametrize("variant", ["native_legacy", "native_completion", "langchain_legacy", "langchain_completion", "openai_responses", "anthropic_messages", "google_gemini_generate_content"]) @pytest.mark.parametrize("streaming", [False, True]) @pytest.mark.parametrize("kind", ["json_schema", "json_object"]) async def test_actual_profile_fields(variant, streaming, kind): transport = variant if variant in {"openai_responses", "anthropic_messages", "google_gemini_generate_content"} else "openai_chat_completions" with provider(transport, False) as (url, sends, replies): config, runtime = runtime_config(url, variant) required = not (transport == "anthropic_messages" and kind == "json_object") request = ModelInvocationRequest(system_prompt="Return one JSON object.", messages=[{"role": "user", "content": "{}"}], output_format=ModelOutputFormat(kind=kind, schema_definition=SCHEMA if kind == "json_schema" else None, required=required)) async def delta(text): pass if streaming: async with runtime.stream_handler(delta): result = await runtime.invoke("fixture", request) else: result = await runtime.invoke("fixture", request) evidence(f"{variant}-{kind}-{'stream' if streaming else 'sync'}", {"physical_requests": sends, "physical_response": [raw.decode() for raw in replies], "result": result.model_dump(mode="json"), "config": model_invocation_parameters(config), "runtime": runtime.get_invocation_runtime_parameters("fixture")}) assert result.response_summary["mode"] == "ok", result.model_dump() assert len(sends) == 1 body = sends[0]["body"] if transport == "openai_chat_completions": token = config.request_profile.chat_token_parameter assert body[token] == 2048 and ("max_tokens" if token == "max_completion_tokens" else "max_completion_tokens") not in body assert body["reasoning_effort"] == "low" assert body["response_format"]["type"] == kind if kind == "json_schema": assert body["response_format"]["json_schema"]["schema"] == SCHEMA assert runtime.get_invocation_runtime_parameters("fixture")["langchain_model_adapter_enabled"] == (variant == "langchain_completion") elif transport == "openai_responses": assert body["max_output_tokens"] == 2048 and body["reasoning"] == {"effort": "low"} assert body["text"]["format"]["type"] == kind if kind == "json_schema": assert body["text"]["format"]["schema"] == SCHEMA elif transport == "anthropic_messages": assert body["max_tokens"] == 2048 and body["thinking"] == {"type": "enabled", "budget_tokens": 1024} if kind == "json_schema": assert body["output_config"]["format"]["schema"] == SCHEMA else: assert "output_config" not in body else: generated = body["generationConfig"] > assert generated["maxOutputTokens"] == 2048 and generated["thinkingConfig"]["thinkingBudget"] == 1024 ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E KeyError: 'thinkingBudget'
